class AddTests(CliBase):
    def path(self, name="f.txt"):
        return os.path.join(self.tmp.name, name)

    def read(self, path):
        with open(path, "rb") as f:
            return f.read()

    def assert_refused(self, argv, path, before):
        code, out, err = self.run_main(argv)
        self.assertEqual(code, 1)
        self.assertEqual(out, "")
        self.assertIn("pennywise: invalid entry:", err)
        if before is None:
            self.assertFalse(os.path.exists(path))
        else:
            self.assertEqual(self.read(path), before)

    def test_creates_missing_file_and_echoes_canonical_line(self):
        path = self.path()
        code, out, err = self.run_main(
            ["add", path, "2024-03-07", "Groceries", "12.5", "  corner shop "])
        self.assertEqual((code, err), (0, ""))
        self.assertEqual(out, "2024-03-07 groceries 12.50 corner shop\n")
        self.assertEqual(self.read(path), b"2024-03-07 groceries 12.50 corner shop\n")

    def test_no_note_no_trailing_space(self):
        path = self.path()
        code, out, _ = self.run_main(["add", path, "2024-03-07", "rent", "-900"])
        self.assertEqual((code, out), (0, "2024-03-07 rent -900.00\n"))
        self.assertEqual(self.read(path), b"2024-03-07 rent -900.00\n")

    def test_appends_after_existing_newline(self):
        path = self.write("2024-03-01 salary 5\n")
        self.run_main(["add", path, "2024-03-02", "a", "+1"])
        self.assertEqual(self.read(path), b"2024-03-01 salary 5\n2024-03-02 a 1.00\n")

    def test_adds_missing_trailing_newline(self):
        path = self.write("2024-03-01 salary 5")
        code, out, _ = self.run_main(["add", path, "2024-03-02", "a", "1"])
        self.assertEqual((code, out), (0, "2024-03-02 a 1.00\n"))
        self.assertEqual(self.read(path), b"2024-03-01 salary 5\n2024-03-02 a 1.00\n")

    def test_existing_bad_lines_do_not_block_add(self):
        path = self.write("garbage here\n")
        code, _, _ = self.run_main(["add", path, "2024-03-02", "a", "1"])
        self.assertEqual(code, 0)
        self.assertEqual(self.read(path), b"garbage here\n2024-03-02 a 1.00\n")

    def test_dash_is_a_filename_not_stdin(self):
        cwd = os.getcwd()
        os.chdir(self.tmp.name)
        self.addCleanup(os.chdir, cwd)
        code, _, _ = self.run_main(["add", "-", "2024-03-02", "a", "1"])
        self.assertEqual(code, 0)
        self.assertEqual(self.read("-"), b"2024-03-02 a 1.00\n")

    def test_utf8_note(self):
        path = self.path()
        self.run_main(["add", path, "2024-03-02", "cafe", "-3", "crème brûlée"])
        self.assertEqual(self.read(path), "2024-03-02 cafe -3.00 crème brûlée\n".encode("utf-8"))

    def test_invalid_amount(self):
        for bad in ("12.505", "1,000.00", "abc", ""):
            path = self.path()
            self.assert_refused(["add", path, "2024-03-07", "x", bad], path, None)

    def test_invalid_dates(self):
        for bad in ("2024-02-30", "2024-3-7", "yesterday", ""):
            path = self.path()
            self.assert_refused(["add", path, bad, "x", "1"], path, None)

    def test_multi_word_or_bad_category(self):
        path = self.write("keep\n")
        before = self.read(path)
        for bad in ("two words", "a 5", " a", "a\t", ""):
            self.assert_refused(["add", path, "2024-03-07", bad, "1"], path, before)

    def test_amount_with_space_refused(self):
        path = self.path()
        self.assert_refused(["add", path, "2024-03-07", "x", "1 2"], path, None)

    def test_note_with_line_break_refused(self):
