        before = self.read(path)
        for bad in ("a\nb", "a\r\nb", "a\n", "\nb", "a\rb", "a\x0bb", "a b"):
            self.assert_refused(["add", path, "2024-03-07", "x", "1", bad], path, before)

    def test_unwritable_target_exit_2(self):
        code, out, err = self.run_main(["add", self.tmp.name, "2024-03-07", "x", "1"])
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertIn("pennywise:", err)

    def test_missing_directory_exit_2(self):
        path = os.path.join(self.tmp.name, "nope", "f.txt")
        code, out, _ = self.run_main(["add", path, "2024-03-07", "x", "1"])
        self.assertEqual((code, out), (2, ""))

    def test_missing_args_exit_2(self):
        code, out, _ = self.run_main(["add", self.path(), "2024-03-07", "x"])
